CREATE TABLE public.rooms (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name text NOT NULL UNIQUE CHECK (char_length(name) BETWEEN 2 AND 60), campus text NOT NULL, author_id uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT ON public.rooms TO anon; GRANT SELECT, INSERT, UPDATE, DELETE ON public.rooms TO authenticated; GRANT ALL ON public.rooms TO service_role; GRANT USAGE, SELECT ON SEQUENCE public.rooms_id_seq TO authenticated, service_role; ALTER TABLE public.rooms ENABLE ROW LEVEL SECURITY; CREATE POLICY "Public rooms" ON public.rooms FOR SELECT TO anon,authenticated USING (true); CREATE POLICY "Create own room" ON public.rooms FOR INSERT TO authenticated WITH CHECK (author_id=auth.uid()); CREATE POLICY "Edit own room" ON public.rooms FOR UPDATE TO authenticated USING (author_id=auth.uid()) WITH CHECK (author_id=auth.uid()); CREATE POLICY "Delete own room" ON public.rooms FOR DELETE TO authenticated USING (author_id=auth.uid()); CREATE TRIGGER rooms_updated BEFORE UPDATE ON public.rooms FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at(); INSERT INTO public.rooms (name,campus) VALUES ('Hostel gist','UNILAG'),('Rate your lecturers','UI'),('Confessions','OAU');